/**
 * The records screen (`design/archetypes/list-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, elementRef, resolveSlot, scope, type Defaults } from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/archetypes/list-page.module.css'
import EmptyState, { type EmptyStateProps } from '../structure/EmptyState'
import Inline from '../layout/Inline'
import PageHeader from '../structure/PageHeader'

export interface ListPageProps {
  /**
   * Vocabulary controls, including the page's one primary action.
   */
  actions?: JSX.Element
  /**
   * A Table composition.
   */
  children: JSX.Element
  description?: string
  empty?: boolean
  /**
   * The empty state, required so the page always defines what it shows with no records.
   */
  emptyState: EmptyStateProps
  /**
   * `sm` controls by convention, and never a solid Button.
   */
  filters?: JSX.Element
  /**
   * The band above the filters (the dashboard block's section cards), with the page's key
   * numbers. By convention it is a `Grid` of Stats in Cards. It is a slot, not part of
   * `children`, because of a law. The body is a panel with Card's surface recipe, and cards do
   * not nest, so stat cards inside it would be boxes inside a box. It also stays in place during
   * the body swap, because a filter that matches nothing does not change how many tickets are
   * open.
   */
  summary?: JSX.Element
  title: string
}

/** The records screen. */
export default function ListPage(given: ListPageProps): JSX.Element {
  const props = mergeProps({ empty: false } as Defaults<ListPageProps, 'empty'>, claimSlot(given))
  return scope(() => {
    const nothing = elementRef<HTMLElement>()
    const records = elementRef<HTMLElement>()
    const actionsSlot = resolveSlot(() => props.actions)
    const filtersSlot = resolveSlot(() => props.filters)
    const recordsPresent = usePresence(
      () => !props.empty,
      () => records.value,
      'listpage.bodyswap',
    )
    const emptyPresent = usePresence(
      () => props.empty,
      () => nothing.value,
      'listpage.bodyswap',
    )
    return (
      <div class={styles.page} data-empty={props.empty ? '' : undefined} data-member="list-page">
        <PageHeader
          title={props.title}
          description={props.description}
          actions={actionsSlot.filled() ? actionsSlot() : undefined}
        />
        {props.summary}
        {filtersSlot.filled() ? (
          <Inline gap={3} wrap={true}>
            {filtersSlot()}
          </Inline>
        ) : null}
        <div class={styles.bodySlot}>
          {recordsPresent() ? (
            <div class={styles.body} ref={records.attach}>
              {props.children}
            </div>
          ) : null}
          {emptyPresent() ? (
            <div class={styles.body} ref={nothing.attach}>
              <EmptyState
                icon={props.emptyState.icon}
                title={props.emptyState.title}
                description={props.emptyState.description}
                action={props.emptyState.action !== undefined ? props.emptyState.action : undefined}
                secondaryAction={
                  props.emptyState.secondaryAction !== undefined
                    ? props.emptyState.secondaryAction
                    : undefined
                }
              />
            </div>
          ) : null}
        </div>
      </div>
    )
  })
}
